import { test, expect } from '@playwright/test';

test.describe('Table Row Context Menu', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display context menu when right-clicking a table row', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table rows exist
    const rows = page.getByRole('row');
    const rowCount = await rows.count();
    expect(rowCount).toBeGreaterThan(0);

    // Get the first table row
    const firstRow = page.getByRole('row').first();
    await expect(firstRow).toBeVisible();

    // Right-click the first table row to open context menu
    await firstRow.click({ button: 'right' });

    // Verify context menu appears
    const contextMenu = page.locator('[data-testid="context-menu"]');
    await expect(contextMenu).toBeVisible();

    // Verify menu items are visible
    const deleteOption = page.getByRole('menuitem', { name: /delete/i });
    const editOption = page.getByRole('menuitem', { name: /edit/i });
    const viewOption = page.getByRole('menuitem', { name: /view/i });
    await expect(deleteOption).toBeVisible();
    await expect(editOption).toBeVisible();
    await expect(viewOption).toBeVisible();

    // Verify context menu has correct position
    const menuBoundingBox = await contextMenu.boundingBox();
    const rowBoundingBox = await firstRow.boundingBox();
    expect(menuBoundingBox.x).toBeGreaterThan(rowBoundingBox.x);
    expect(menuBoundingBox.y).toBeGreaterThan(rowBoundingBox.y);

    // Click on 'Edit' option
    await editOption.click();

    // Verify context menu closes
    await expect(contextMenu).not.toBeVisible();

    // Verify edit modal appears
    const editModal = page.locator('[data-testid="edit-modal"]');
    await expect(editModal).toBeVisible();
  });

  test('should not display context menu when right-clicking outside a table row', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Get the first table row
    const firstRow = page.getByRole('row').first();
    await expect(firstRow).toBeVisible();

    // Right-click on the table header (outside a row)
    const tableHeader = page.getByRole('columnheader').first();
    await tableHeader.click({ button: 'right' });

    // Verify context menu does not appear
    const contextMenu = page.locator('[data-testid="context-menu"]');
    await expect(contextMenu).not.toBeVisible();

    // Right-click on empty space in the table body
    const tableBody = page.getByRole('rowgroup');
    const emptySpace = page.locator('[data-testid="table-body-empty-space"]');
    await emptySpace.click({ button: 'right' });

    // Verify context menu still does not appear
    await expect(contextMenu).not.toBeVisible();

    // Verify table is still visible
    await expect(table).toBeVisible();

    // Verify no edit modal is open
    const editModal = page.locator('[data-testid="edit-modal"]');
    await expect(editModal).not.toBeVisible();
  });
});
